int check() {
    // Build adjacency, check SC
    int adj[10][10] = {0};
    int prev = 0; // 0-indexed, town 1 = index 0
    for (int i = 0; i < M; i++) {
        adj[prev][seq[i]] = 1;
        prev = seq[i];
    }
    // Floyd-Warshall
    int r[10][10];
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) r[i][j] = (i==j) || adj[i][j];
    for (int k = 0; k < N; k++) for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) if (r[i][k]&&r[k][j]) r[i][j]=1;
    for (int i = 0; i < N; i++) for (int j = 0; j < N; j++) if (!r[i][j]) return 0;
