#include <stdio.h>
#include <stdlib.h>

#define MOD 1000000007LL

/*
We count sequences c_1..c_M, c_i in [1..N], such that if we add directed edges
(1 -> c1), (c1 -> c2), ..., (c_{M-1} -> c_M),
then the resulting directed graph on N vertices is strongly connected.

Key fact:
A directed graph formed by a walk v0=1, v1, ..., vM (edges v_{i-1}->v_i) is strongly connected
iff every town appears at least once in the sequence of visited vertices v0..vM, and
the last town vM = 1.

Reason:
- In such a path graph, for every visited vertex there is a directed path along the walk to later visited vertices.
- To return from any vertex to earlier ones, the walk must eventually come back, and for strong connectivity
  in particular must return to 1, so vM=1.
- If every town appears and vM=1, then for any two towns a,b:
  go from a forward along the walk until the final 1, then continue along the walk from 1 until the first occurrence of b.
  Hence a reaches b.

Thus the problem becomes:
Count sequences v1..vM with:
- v0 = 1 fixed
- vM = 1
- every town 2..N appears at least once among v1..v_{M-1}
(1 may appear any number of times)

So among positions 1..M-1 (there are L=M-1 positions), we need all N-1 non-1 towns to appear at least once,
each position taking one of N towns.
Number = sum_{k=0}^{N-1} (-1)^k C(N-1,k) (N-k)^L
by inclusion-exclusion.

Special cases:
- N=1: only town 1 exists, every sequence works iff c_M=1 automatically true since only choice is 1.
  Answer = 1 for any M.
- If M-1 < N-1, impossible to include all towns 2..N at least once => 0.
*/

long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    long long N, M;
    if (scanf("%lld %lld", &N, &M) != 2) return 0;

    if (N == 1) {
        printf("1\n");
        return 0;
    }

    long long L = M - 1;
    if (L < N - 1) {
        printf("0\n");
        return 0;
    }

    long long *fact = (long long *)malloc((N + 1) * sizeof(long long));
    long long *invfact = (long long *)malloc((N + 1) * sizeof(long long));

    fact[0] = 1;
    for (long long i = 1; i <= N; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[N] = mod_pow(fact[N], MOD - 2);
    for (long long i = N; i >= 1; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long ans = 0;
    for (long long k = 0; k <= N - 1; k++) {
        long long comb = fact[N - 1] * invfact[k] % MOD * invfact[N - 1 - k] % MOD;
        long long ways = mod_pow(N - k, L);
        long long term = comb * ways % MOD;
        if (k & 1) {
            ans -= term;
            if (ans < 0) ans += MOD;
        } else {
            ans += term;
            if (ans >= MOD) ans -= MOD;
        }
    }

    printf("%lld\n", ans);

    free(fact);
    free(invfact);
    return 0;
}

