#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, M;
    cin >> N >> M;

    // We count sequences c_1..c_M over {1..N} such that
    // edges (1 -> c1), (c1 -> c2), ..., (c_{M-1} -> c_M)
    // make the whole directed graph strongly connected.
    //
    // Since the walk itself is a directed path visiting the towns in order,
    // for the resulting graph to be strongly connected, every town must appear
    // at least once among:
    // 1, c1, c2, ..., c_M
    //
    // Indeed, if all towns appear, then along the path we can go from an earlier
    // occurrence to a later occurrence. Because 1 is the first vertex, every
    // visited town is reachable from 1. Also, after the last occurrence of any
    // town x, the path eventually reaches c_M; to return to earlier towns, those
    // towns must appear again later unless x is last, etc.
    //
    // A standard characterization here is:
    // the graph formed by consecutive transitions of a sequence is strongly
    // connected iff every town appears at least once and c_M = 1 is NOT required?
    //
    // Let's derive correctly.
    //
    // The graph consists only of edges of the form a_i -> a_{i+1}, where
    // a_0 = 1, a_i = c_i.
    //
    // Condensation DAG of any directed graph obtained from a walk is a path-like
    // structure respecting time order. For strong connectivity, all vertices used
    // must belong to one SCC. This happens iff for every cut between positions t
    // and t+1, there is some vertex appearing on both sides; equivalently the
    // sequence cannot be split into two parts with disjoint sets of towns.
    //
    // Counting such sequences directly is hard, but there is a classic inclusion-
    // exclusion result for strong connectivity of a directed path-trace:
    // it is equivalent to every town appearing at least once in the sequence
    // a_0..a_M and the last occurrence intervals being interleaved so no prefix
    // has a set disjoint from suffix.
    //
    // However, for this specific AtCoder-style problem, the intended condition is
    // that after paving roads while moving, it should be possible to travel
    // between any two towns *that exist in the kingdom*, so all towns must be on
    // the tour, and because roads are along the tour direction, to get back to
    // earlier towns the tour must end at 1. Then if every town appears at least
    // once and c_M = 1, the graph is strongly connected: from any town, follow
    // the path to the end (1), then from 1 follow the path to any later occurrence
    // of the destination.
    //
    // Conversely, if c_M != 1, the last town has outdegree 0, so unless N=1 it
    // cannot reach others; thus strong connectivity requires c_M = 1.
    //
    // Therefore we need sequences c of length M with:
    // - c_M = 1
    // - every town 1..N appears at least once in c_0..c_M where c_0=1
    //
    // Since town 1 already appears at c_0, among c_1..c_{M-1} we need every town
    // 2..N to appear at least once; c_M is fixed to 1.
    //
    // So count sequences of length L = M-1 over alphabet size N such that each of
    // the N-1 special symbols {2..N} appears at least once; symbol 1 may appear any
    // number of times.
    //
    // By inclusion-exclusion:
    // answer = sum_{k=0}^{N-1} (-1)^k * C(N-1,k) * (N-k)^(M-1)
    //
    // Edge cases:
    // N=1: any sequence must have c_M=1, and all towns are covered automatically.
    // Since only town 1 exists, exactly 1 sequence for any M (all ones).
    //
    // Also if M-1 < N-1 and N>1, answer becomes 0 automatically by IE.

    if (N == 1) {
        cout << 1 % MOD << '\n';
        return 0;
    }

    long long L = M - 1;

    vector<long long> fact(N + 1), invfact(N + 1);
    fact[0] = 1;
    for (int i = 1; i <= N; ++i) fact[i] = fact[i - 1] * i % MOD;

    auto modpow = [&](long long a, long long e) {
        long long r = 1 % MOD;
        a %= MOD;
        while (e > 0) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    };

    invfact[N] = modpow(fact[N], MOD - 2);
    for (int i = (int)N; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

    auto C = [&](long long n, long long r) -> long long {
        if (r < 0 || r > n) return 0;
        return fact[n] * invfact[r] % MOD * invfact[n - r] % MOD;
    };

    long long ans = 0;
    for (long long k = 0; k <= N - 1; ++k) {
        long long ways = C(N - 1, k) * modpow(N - k, L) % MOD;
        if (k % 2 == 0) {
            ans += ways;
        } else {
            ans -= ways;
        }
        ans %= MOD;
    }

    if (ans < 0) ans += MOD;
    cout << ans % MOD << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();

        long fact = 1;
        for (int i = 2; i < N; i++) {
            fact = fact * i % MOD;
        }

        long pow = 1;
        long base = N % MOD;
        int exp = M - N;
        while (exp > 0) {
            if ((exp & 1) == 1) pow = pow * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }

        long ans = fact * pow % MOD;
        System.out.println(ans);
    }
}

import java.util.*;
import java.math.*;

public class Main {
    static final long MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        long M = sc.nextLong();

        // Answer = sum_{k=1}^{N} (-1)^{N-k} * C(N-1, k-1) * k^M
        long ans = 0;
        long[] C = new long[(int)N];
        C[0] = 1;
        for (int i = 1; i < N; i++) C[i] = C[i-1] * (N-1 - (i-1)) % MOD * modInverse(i, MOD) % MOD;

        for (int k = 1; k <= N; k++) {
            long term = C[k-1] % MOD * modPow(k, M, MOD) % MOD;
            if ((N - k) % 2 == 0) ans = (ans + term) % MOD;
            else ans = (ans - term + MOD) % MOD;
        }
        System.out.println(ans);
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1; base %= mod;
        while (exp > 0) { if ((exp&1)==1) result = result*base%mod; base=base*base%mod; exp>>=1; }
        return result;
    }
    static long modInverse(long a, long mod) { return modPow(a, mod-2, mod); }
}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();

        // dp[k] = number of ways after current day such that
        // exactly k distinct towns have appeared among:
        // start town 1 and visited towns so far.
        long[] dp = new long[N + 1];
        dp[1] = 1; // initially only town 1 is known

        for (int day = 1; day <= M; day++) {
            long[] ndp = new long[N + 1];
            for (int k = 1; k <= N; k++) {
                long cur = dp[k];
                if (cur == 0) continue;

                // Choose next town among already seen towns: k choices
                ndp[k] = (ndp[k] + cur * k) % MOD;

                // Choose next town among unseen towns: N-k choices
                if (k < N) {
                    ndp[k + 1] = (ndp[k + 1] + cur * (N - k)) % MOD;
                }
            }
            dp = ndp;
        }

        // For strong connectivity of the final directed graph formed by edges
        // 1->c1, c1->c2, ..., c_{M-1}->cM,
        // it is necessary and sufficient that every town appears at least once
        // in the sequence [1, c1, ..., cM].
        System.out.println(dp[N] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
